) AS v(id, title, description, status, vals)
CROSS JOIN public.projects p
WHERE p.project_code = 'SEED334-PRJ-08'
ON CONFLICT (id) DO NOTHING;

-- Step → runbook labels carry the runbook's display ID once Admin ID Generation has assigned it.
UPDATE public.local_register_records s
SET field_values = jsonb_set(s.field_values, '{runbook}',
      jsonb_build_array(jsonb_build_object('id', rb.id::text,
        'label', CASE WHEN COALESCE(rb.display_id, '') <> '' THEN rb.display_id || ' – ' || rb.title ELSE rb.title END)))
FROM public.local_register_records rb
WHERE s.register_id = '00000000-0000-4000-9001-000000000043'::uuid
  AND s.id::text LIKE '00000000-0000-4000-b043-%'
  AND rb.id::text = s.field_values -> 'runbook' -> 0 ->> 'id'
  AND s.field_values -> 'runbook' -> 0 ->> 'label' IS DISTINCT FROM
      CASE WHEN COALESCE(rb.display_id, '') <> '' THEN rb.display_id || ' – ' || rb.title ELSE rb.title END;

COMMIT;

-- Check: runbooks with their step counts and progress.
SELECT rb.display_id, rb.title, rb.status,
       count(s.id) AS steps,
       count(s.id) FILTER (WHERE s.status IN ('done', 'skipped')) AS done,
       sum((s.field_values ->> 'records_loaded')::numeric) AS records_loaded
FROM public.local_register_records rb
LEFT JOIN public.local_register_records s
  ON s.register_id = '00000000-0000-4000-9001-000000000043'::uuid AND s.is_deleted = FALSE
 AND s.field_values -> 'runbook' @> jsonb_build_array(jsonb_build_object('id', rb.id::text))
WHERE rb.register_id = '00000000-0000-4000-9001-000000000042'::uuid AND rb.id::text LIKE '00000000-0000-4000-b042-%'
GROUP BY rb.id, rb.display_id, rb.title, rb.status
ORDER BY rb.id;
